-- V54: Hospital ICD diagnosis catalog (favorites / cached subset for OPD assessment)
-- Does not alter clinical.diagnoses; code+text still denormalized onto the encounter row.

CREATE TABLE IF NOT EXISTS hospital.diagnosis_catalog (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id       UUID NOT NULL,
    hospital_id     UUID NOT NULL REFERENCES hospital.hospitals(id),
    branch_id       UUID REFERENCES hospital.branches(id),
    icd_code        VARCHAR(50) NOT NULL,
    name            VARCHAR(500) NOT NULL,
    category        VARCHAR(100),
    active          BOOLEAN NOT NULL DEFAULT TRUE,
    version         BIGINT NOT NULL DEFAULT 0,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    created_by      UUID,
    updated_by      UUID,
    deleted_at      TIMESTAMPTZ
);

CREATE UNIQUE INDEX IF NOT EXISTS uq_diagnosis_catalog_hospital_code
    ON hospital.diagnosis_catalog (hospital_id, COALESCE(branch_id, '00000000-0000-0000-0000-000000000000'), lower(icd_code))
    WHERE deleted_at IS NULL;

CREATE INDEX IF NOT EXISTS idx_diagnosis_catalog_hospital
    ON hospital.diagnosis_catalog (hospital_id, active)
    WHERE deleted_at IS NULL;

